params.command:
$ErrorActionPreference='Stop'
$repo=Join-Path $env:USERPROFILE 'local-ai-workspaces\mhw-mods'
git -C $repo fetch origin --prune
$base=(git -C $repo rev-parse origin/main).Trim()
$tmp=Join-Path $env:TEMP ('branchzero-swarm-'+[guid]::NewGuid().ToString('N'))
git -C $repo worktree add --detach $tmp origin/main | Out-Null
try {
 foreach($c in @('aa1500f0e16f4a2182dfd6397888417e4912b8ff','8de8219844629786e91853cc8335a60784db3d33','df74b159fda02723dd85a74a4b75b5de47b8b631')){git -C $tmp cherry-pick $c;if($LASTEXITCODE -ne 0){$conf=@(git -C $tmp diff --name-only --diff-filter=U);[pscustomobject]@{status='conflict';base=$base;commit=$c;conflicts=$conf}|ConvertTo-Json -Compress;exit 21}}
 Push-Location (Join-Path $tmp 'tools\agent-control');try{npm run check;if($LASTEXITCODE -ne 0){throw 'CHECK_FAILED'};npm test;if($LASTEXITCODE -ne 0){throw 'TEST_FAILED'}}finally{Pop-Location}
 git -C $repo fetch origin
 if((git -C $repo rev-parse origin/main).Trim() -ne $base){throw 'MAIN_MOVED'}
 git -C $tmp push origin HEAD:main
 if($LASTEXITCODE -ne 0){throw 'PUSH_MAIN_FAILED'}
 [pscustomobject]@{status='integrated';base=$base;head=(git -C $tmp rev-parse HEAD).Trim()}|ConvertTo-Json -Compress
} finally { git -C $repo worktree remove --force $tmp 2>$null | Out-Null }
